  schemes_modal_intro: "ଏହି କଥାଗୁଡ଼ିକ ଆପଣଙ୍କ KARIGARI ପ୍ରୋଫାଇଲରୁ ଯାଞ୍ଚ କରାଯାଇପାରିବ ନାହିଁ। ଆପଣଙ୍କ ପାଇଁ ସତ ହେଲେ ହିଁ ପ୍ରତ୍ୟେକଟିରେ ଟିକ୍ କରନ୍ତୁ।",
  schemes_modal_honesty: "KARIGARI କୌଣସି ସରକାରୀ ସିଷ୍ଟମକୁ କିଛି ପଠାଏ ନାହିଁ। ଆବେଦନ ଆପଣ ନିଜେ ଅଫିସିଆଲ୍ ପୋର୍ଟାଲରେ ଦାଖଲ କରିବେ — ଏଠାରେ କେବଳ ଆପଣଙ୍କ ଟ୍ରାକରରେ ଏହା ଲେଖା ହୋଇ ରହିବ।",
  schemes_modal_confirm: "ନିଶ୍ଚିତ କରି ଟ୍ରାକ୍ କରନ୍ତୁ",
