  schemes_modal_tick_all: "ଆଗକୁ ବଢ଼ିବା ପାଇଁ ପ୍ରତ୍ୟେକ ବାକ୍ସରେ ଟିକ୍ କରନ୍ତୁ",
  scheme_pm_vishwakarma_name: "PM ବିଶ୍ୱକର୍ମା ଯୋଜନା",
  scheme_pm_vishwakarma_desc: "ନିଜ ହାତ ଓ ଯନ୍ତ୍ରପାତିରେ କାମ କରୁଥିବା ପାରମ୍ପରିକ କାରିଗର ଓ ଶିଳ୍ପୀଙ୍କ ପାଇଁ କେନ୍ଦ୍ର ସରକାରଙ୍କ ଯୋଜନା; ପଞ୍ଜିକରଣ CSC ସହାୟତାରେ ହୁଏ।",
  scheme_pm_vishwakarma_benefit: "₹15,000 ଟୁଲକିଟ୍ ଇ-ଭାଉଚର • ବନ୍ଧକ ବିନା ₹3 ଲକ୍ଷ ପର୍ଯ୍ୟନ୍ତ 5% ସୁଧରେ ଋଣ • ତାଲିମ ପାଇଁ ଦିନକୁ ₹500 ଭତ୍ତା",
  scheme_pm_vishwakarma_note: "ପଞ୍ଜିକରଣ ଏକ କମନ୍ ସର୍ଭିସ୍ ସେଣ୍ଟର (CSC)ରେ ବାୟୋମେଟ୍ରିକ୍ ଆଧାର ପ୍ରମାଣୀକରଣ ସହିତ ସମ୍ପୂର୍ଣ୍ଣ ହୁଏ।",
  scheme_nsfdc_name: "NSFDC — ରାଷ୍ଟ୍ରୀୟ ଅନୁସୂଚିତ ଜାତି ଆର୍ଥିକ ଓ ବିକାଶ ନିଗମ",
  scheme_nsfdc_desc: "ଅନୁସୂଚିତ ଜାତି କାରିଗରଙ୍କ ପାଇଁ ରିହାତି ଋଣ, କୌଶଳ ତାଲିମ ଓ ବଜାର ସହାୟତା; ରାଜ୍ୟ ଚ୍ୟାନେଲାଇଜିଂ ଏଜେନ୍ସି ଓ ବ୍ୟାଙ୍କ ମାଧ୍ୟମରେ ମିଳେ।",
  scheme_nsfdc_benefit: "ରିହାତି ଦରରେ ମିଆଦୀ ଋଣ, କ୍ଷୁଦ୍ର ଋଣ, କୌଶଳ ତାଲିମ ଓ ବଜାର ସହାୟତା",
  scheme_nsfdc_note: "ଆବେଦନ ଆପଣଙ୍କ ରାଜ୍ୟ ଚ୍ୟାନେଲାଇଜିଂ ଏଜେନ୍ସି (SCA) କିମ୍ବା ସହଯୋଗୀ ବ୍ୟାଙ୍କ ଶାଖା ମାଧ୍ୟମରେ ଦାଖଲ ହୁଏ।",
  scheme_nbcfdc_name: "NBCFDC — ରାଷ୍ଟ୍ରୀୟ ପଛୁଆ ବର୍ଗ ଆର୍ଥିକ ଓ ବିକାଶ ନିଗମ",
  scheme_nbcfdc_desc: "ଅନ୍ୟାନ୍ୟ ପଛୁଆ ବର୍ଗ (OBC) ଓ ଆର୍ଥିକ ଦୁର୍ବଳ ବର୍ଗ (EWS) ପାଇଁ ରିହାତି ମିଆଦୀ ଋଣ ଓ କ୍ଷୁଦ୍ର ଋଣ; ଅନଲାଇନ୍ ପଞ୍ଜିକରଣ ଓ ଚ୍ୟାନେଲ୍ ପାର୍ଟନର ମାଧ୍ୟମରେ।",
  scheme_nbcfdc_benefit: "ରୋଜଗାର ସୃଷ୍ଟିକାରୀ କାମ ପାଇଁ ରିହାତି ଦରରେ ମିଆଦୀ ଋଣ ଓ କ୍ଷୁଦ୍ର ଋଣ",
  scheme_nbcfdc_note: "",
  scheme_gem_seller_name: "GeM ବିକ୍ରେତା ପଞ୍ଜିକରଣ",
  scheme_gem_seller_desc: "ସରକାରୀ ଇ-ମାର୍କେଟପ୍ଲେସରେ ବିକ୍ରେତା ଭାବେ ପଞ୍ଜିକରଣ କରି ବିନା ଦଲାଲରେ ସିଧାସଳଖ ସରକାରୀ ବିଭାଗ ଓ PSUକୁ ବିକ୍ରି କରନ୍ତୁ।",
  scheme_gem_seller_benefit: "ସରକାରୀ କ୍ରେତାଙ୍କ ପାଖରେ ସିଧାସଳଖ ପହଞ୍ଚ • ମାଗଣା ବିକ୍ରେତା ପଞ୍ଜିକରଣ",
  scheme_gem_seller_note: "ପଞ୍ଜିକରଣ ସମୟରେ PAN ଦରକାର। କର ଲାଗୁ ହେଉଥିବା ଉତ୍ପାଦ ବର୍ଗ ପାଇଁ ଅତିରିକ୍ତ ଭାବେ GST ପଞ୍ଜିକରଣ ମଧ୍ୟ ଦରକାର ହୋଇପାରେ।",
  scheme_ahvy_name: "AHVY — ଆମ୍ବେଦକର ହସ୍ତଶିଳ୍ପ ବିକାଶ ଯୋଜନା",
  scheme_ahvy_desc: "ଜାତୀୟ ହସ୍ତଶିଳ୍ପ ବିକାଶ କାର୍ଯ୍ୟକ୍ରମ ଅଧୀନରେ କ୍ଲଷ୍ଟର-ଭିତ୍ତିକ ହସ୍ତଶିଳ୍ପ ବିକାଶ; ବିକାଶ କମିଶନର (ହସ୍ତଶିଳ୍ପ) କାର୍ଯ୍ୟାଳୟ ଦ୍ୱାରା ପରିଚାଳିତ।",
  scheme_ahvy_benefit: "ଟୁଲକିଟ୍ (~₹5,000) • ମାର୍ଜିନ୍ ମନି (କାରିଗର ପିଛା ~₹4,000) • କମନ୍ ଫାସିଲିଟି ସେଣ୍ଟର • ବଜାର ଓ ପ୍ରଦର୍ଶନୀ ଭ୍ରମଣ",
  scheme_ahvy_note: "ଏକ ପଞ୍ଜିକୃତ ଉତ୍ପାଦକ ଗୋଷ୍ଠୀ, SHG କିମ୍ବା ସମବାୟ ମାଧ୍ୟମରେ ଆବେଦନ କରାଯାଏ, ଯେଉଁଥିରେ ଅତି କମରେ 50% ସଦସ୍ୟ କ୍ଲଷ୍ଟର କାରିଗର ହୋଇଥିବେ।",
  scheme_ondc_name: "ONDC ବିକ୍ରେତା ଅନବୋର୍ଡିଂ",
  scheme_ondc_desc: "ଓପନ୍ ନେଟୱାର୍କ ଫର୍ ଡିଜିଟାଲ୍ କମର୍ସ (ONDC)ରେ ଆପଣଙ୍କ ଶିଳ୍ପ ତାଲିକାଭୁକ୍ତ କରନ୍ତୁ ଏବଂ ଯେକୌଣସି ONDC ବିକ୍ରେତା ଆପ୍ ମାଧ୍ୟମରେ ଦେଶସାରା କ୍ରେତାଙ୍କ ପାଖରେ ପହଞ୍ଚନ୍ତୁ।",
  scheme_ondc_benefit: "ଖୋଲା ଇ-କମର୍ସ ନେଟୱାର୍କରେ ଦେଶସାରା କ୍ରେତାଙ୍କ ପାଖରେ ପହଞ୍ଚ, କୌଣସି ପ୍ଲାଟଫର୍ମରେ ବନ୍ଧା ପଡ଼ିବା ବିନା",
  scheme_ondc_note: "ଅନବୋର୍ଡିଂ ଏକ ONDC ବିକ୍ରେତା ଆପ୍ (ନେଟୱାର୍କ ଅଂଶୀଦାର) ମାଧ୍ୟମରେ ହୁଏ। CGST ଧାରା 9(5) ଅଧୀନରେ ଆପଣଙ୍କ ବର୍ଗ ଛାଡ଼ ପାଇ ନଥିଲେ GST ଦରକାର।",
  rule_notified_trade: "ଶିଳ୍ପଟି PM ବିଶ୍ୱକର୍ମାର 18ଟି ବିଜ୍ଞପ୍ତିଭୁକ୍ତ ବୃତ୍ତି ମଧ୍ୟରୁ ଗୋଟିଏ",
  rule_age_18: "ମୋର ବୟସ 18 ବର୍ଷ କିମ୍ବା ତାହାଠାରୁ ଅଧିକ",
  rule_not_govt_employee: "ମୁଁ ସରକାରୀ କର୍ମଚାରୀ ନୁହେଁ, ଏବଂ ମୋ ପରିବାରର କେହି ମଧ୍ୟ ନୁହନ୍ତି",
  rule_no_similar_credit_5y: "ଗତ 5 ବର୍ଷ ଭିତରେ ମୁଁ PMEGP, PM ସ୍ୱନିଧି କିମ୍ବା ମୁଦ୍ରା ଋଣ ନେଇ ନାହିଁ",
  rule_one_per_family: "ଏହି ଲାଭ ପାଇଁ ମୋ ପରିବାରରୁ କେବଳ ମୁଁ ହିଁ ଆବେଦନ କରୁଛି",
